47	    let mut state = game_at_step(Step::PrecombatMain, P0);
48	
49	    let card = spell_in_hand(&mut state, &reg, "Geistflame", P0);
50	
51	    // Give exactly {R} (enough for normal Geistflame, not enough for {3}{R} flashback).
52	    state.get_player_mut(P0).mana_pool.add(ManaType::Red, 1);
53	
54	    let legal = engine::legal_actions(&state, &reg);
55	    let has_cast = legal.actions.iter().any(|a| {
56	        matches!(a, Action::CastSpell { object_id, .. } if *object_id == card)
57	    });
58	    // It IS offered — as a normal cast from hand at cost {R}.
59	    assert!(has_cast,
60	        "Geistflame should be castable from hand at normal cost R");
61	}
