371	    // The spell is cast from hand (removing it), then draws 2, discards 1 => net +1 from the
372	    // state before casting. But hand_before was measured before we created the spell card.
373	    // So: hand_before (0) -> +1 (create DR) -> -1 (cast DR) -> +2 (draw) -> -1 (discard) = 1
374	    assert_eq!(hand_after, hand_before + 1,
375	        "Desperate Ravings should result in net +1 hand size (draw 2, discard 1, minus the spell)");
376	}
